window.CLAVES_IA={"2":{"11":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":74,"cita":"Know escape ramp locations on your route.","nota":"La sección de conducción en montaña lo pide expresamente antes de bajar una pendiente."},"12":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":80,"cita":"2.20.1 – Protect the Area. The first thing to do at an accident scene is to keep another accident from happening in the same spot.","nota":"Avisar a las autoridades es el paso 2; sin radio CB, el manual dice esperar a que el área esté protegida antes de ir a llamar."},"13":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 19, pregunta 49","nota":"Enunciado y opciones idénticos a la hoja 19, pregunta 49, cuya clave sí venía impresa en el folleto."},"14":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 11, pregunta 37","nota":"Enunciado y opciones idénticos a la hoja 11, pregunta 37, cuya clave sí venía impresa en el folleto."},"15":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":50,"cita":"Put your turn signal on before changing lanes. Change lanes slowly and smoothly.","nota":"Las dos mitades de la opción B están literales en el manual."},"16":{"clave":"A","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":45,"cita":"Rough acceleration can cause mechanical damage. When pulling a trailer, rough acceleration can damage the coupling.","nota":"Por descarte: el manual nombra el daño mecánico y el daño al acoplamiento, y no menciona daño a las llantas."},"17":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":51,"cita":"When putting out the triangles, hold them between yourself and the oncoming traffic for your own safety.","nota":"Coincide palabra por palabra con la opción."},"18":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":92,"cita":"Dry bulk tanks require special care because they have a high center of gravity, and the load can shift.","nota":"Misma frase del manual, sección 3.4.1."},"19":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 31, pregunta 50","nota":"Enunciado y opciones idénticos a la hoja 31, pregunta 50, cuya clave sí venía impresa en el folleto."},"20":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":65,"cita":"Many heavy motor vehicle accidents occur between midnight and 6 a.m.","nota":"La misma página descarta A y B: «Most people are less alert at night, especially after midnight»."},"21":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":67,"cita":"Dim your lights within 500 feet of an oncoming vehicle and when following another vehicle within 500 feet.","nota":"Poner luces altas al rebasar es justo lo contrario de lo que pide el manual. En cambio tocar el claxon sí viene sugerido (pág. 50)."}},"4":{"33":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 23, pregunta 37","nota":"Enunciado y opciones idénticos a la hoja 23, pregunta 37, cuya clave sí venía impresa en el folleto."},"34":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":83,"cita":"Alcohol affects judgment, vision, coordination, and reaction time. […] This is a fixed rate, so only time, not black coffee or a cold shower, will sober you up.","nota":"El manual no dice que el juicio se afecte «primero», pero descarta A (el cuerpo elimina alcohol a ritmo fijo) y B (el alcohol empeora el tiempo de reacción)."},"35":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":51,"cita":"This is the distance your vehicle travels, in ideal conditions, from the time your eyes see a hazard until your brain recognizes it.","nota":"Definición literal de perception distance."},"36":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":48,"cita":"Most good drivers look at least 12 to 15 seconds ahead. […] At highway speeds, it is about a quarter of a mile.","nota":"Un cuarto de milla a velocidad de carretera."},"37":{"clave":"A","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":51,"cita":"Some slow-moving vehicles have an orange and red triangle on their back, such as road maintenance vehicles, which usually travel at 25 mph or less.","nota":"Esta pregunta depende de la figura impresa en la hoja. Si el triángulo naranja y rojo es el que aparece en el escaneo, la respuesta es «slow-moving vehicle». Compruébalo contra la imagen."},"38":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 21, pregunta 13","nota":"Enunciado y opciones idénticos a la hoja 21, pregunta 13, cuya clave sí venía impresa en el folleto."},"39":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 23, pregunta 39","nota":"Enunciado y opciones idénticos a la hoja 23, pregunta 39, cuya clave sí venía impresa en el folleto."},"40":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":46,"cita":"Back slowly. Back and turn toward the driver's side whenever possible. Use a helper whenever possible. […] Before you begin backing, work out a set of hand signals that you both understand.","nota":"Por descarte: A y B están literales en la lista de reglas del manual, así que la afirmación falsa es la de golpear el andén."},"41":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":79,"cita":"Skids caused by acceleration usually happen on ice or snow. Taking your foot off the accelerator can easily stop them.","nota":"OJO: el manual vigente corrige un patinaje por FRENADO con «Stop Braking», opción que el cuestionario no ofrece. De las tres impresas, quitar el acelerador es la única que el manual respalda para hielo o nieve."},"42":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":96,"cita":"There are 9 different 4 inch, diamond-shaped hazard labels.","nota":"Cuatro pulgadas y forma de diamante, no circular."}},"5":{"1":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":113,"cita":"5.4.7 – Low Air Pressure. If the low air pressure warning comes on, stop and safely park your vehicle as soon as possible.","nota":"Coincide literalmente con la opción."}},"6":{"2":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":112,"cita":"Therefore, at 55 mph for an average driver under good traction and brake conditions, the total stopping distance is over 450 feet.","nota":"Más de 450 pies, o sea más de 300."},"3":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":102,"cita":"Pressing and releasing the pedal unnecessarily can let air out faster than the compressor can replace it.","nota":"Eso es exactamente la pérdida de presión de aire."},"4":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":109,"cita":"For dual air systems, the pressure should build from approximately 85 to 100 psi within 45 seconds.","nota":"Las mismas cifras del enunciado."},"5":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":104,"cita":"The braking power of spring brakes depends on the brakes being in adjustment.","nota":"Frase literal."},"6":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":103,"cita":"5.1.10 – Application Pressure Gauge. This gauge shows how much air pressure you are applying to the brakes.","nota":"Definición literal. Los tanques los mide otro manómetro distinto."},"7":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":104,"cita":"Powerful springs are held back by air pressure when driving. If the air pressure is removed, the springs put on the brakes.","nota":"Es el aire el que retiene los resortes, no al revés."},"8":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 13, pregunta 14","nota":"Enunciado y opciones idénticos a la hoja 13, pregunta 14, cuya clave sí venía impresa en el folleto."},"9":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":75,"cita":"With this method, you apply the brakes as hard as you can without locking the wheels.","nota":"Definición de controlled braking. La opción B describe stab braking, que es el otro método."},"10":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":102,"cita":"5.1.5 – Alcohol Evaporator […] This helps to reduce the risk of ice in air brake valves and other parts during cold weather.","nota":"El mismo párrafo aclara que el drenaje diario de tanques sigue siendo necesario, lo que descarta B."},"11":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":110,"cita":"Test Service Brakes: Wait for normal air pressure, release the parking brake, move the vehicle forward slowly (about 5 mph), and apply the brakes firmly using the brake pedal.","nota":"Procedimiento literal del manual."},"12":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":74,"cita":"The use of brakes on a long and/or steep downgrade is only a supplement to the braking effect of the engine.","nota":"Frase literal."},"13":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":75,"cita":"You should brake in a way that will keep your vehicle in a straight line and allow you to turn if it becomes necessary.","nota":"Frase literal."}},"8":{"1":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":52,"cita":"55 [mph] 419' Total Stopping Distance […] At 60 mph, your stopping distance is greater than the length of an American football field.","nota":"El manual vigente da 419 pies a 55 mph; un campo de fútbol americano mide 300. De las tres opciones impresas, «la longitud de un campo» es la única del orden correcto."},"2":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":55,"cita":"Increase Your Following Distance. Open up room in front of you to help you avoid having to make sudden speed or direction changes.","nota":"Es la recomendación literal del manual para cuando te van pegado atrás."},"3":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 29, pregunta 24","nota":"Enunciado y opciones idénticos a la hoja 29, pregunta 24, cuya clave sí venía impresa en el folleto."},"4":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":117,"cita":"6.1.6 – Turn Wide. When a vehicle goes around a corner, the rear wheels follow a different path than the front wheels. […] the rear wheels of the last trailer will off-track the most.","nota":"El término del manual es off-tracking."},"5":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":58,"cita":"Make sure you are going slowly enough before you get on the curved part of an off or on ramp.","nota":"Además el manual advierte que el límite señalado en las rampas está pensado para autos, no para vehículos pesados."},"6":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 21, pregunta 20","nota":"Enunciado y opciones idénticos a la hoja 21, pregunta 20, cuya clave sí venía impresa en el folleto."},"7":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":80,"cita":"Vehicle Inspection. Make a complete inspection of the electrical, fuel, and exhaust systems, tires, and cargo. […] Cargo. Flammable cargo, improperly sealed or loaded cargo, and poor ventilation.","nota":"Por descarte: la lista de causas de incendio incluye el sistema eléctrico y la ventilación de la carga, pero no el nivel de líquido de la batería."},"8":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":81,"cita":"A burning tire must be cooled. Lots of water may be required. […] do not use water on an electrical fire (can cause shock) or a gasoline fire (will spread the flames).","nota":"La misma lista descarta A y B."}},"10":{"21":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 29, pregunta 23","nota":"Enunciado y opciones idénticos a la hoja 29, pregunta 23, cuya clave sí venía impresa en el folleto."},"22":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 27, pregunta 9","nota":"Enunciado y opciones idénticos a la hoja 27, pregunta 9, cuya clave sí venía impresa en el folleto."},"23":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 27, pregunta 8","nota":"Enunciado y opciones idénticos a la hoja 27, pregunta 8, cuya clave sí venía impresa en el folleto."},"24":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 29, pregunta 31","nota":"Enunciado y opciones idénticos a la hoja 29, pregunta 31, cuya clave sí venía impresa en el folleto."},"25":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":110,"cita":"Test Parking Brake: Fasten your seat belt. Set the parking brake, and gently pull against it in a low gear to test that the parking brake will hold. Test Service Brakes: Wait for normal air pressure, release the parking brake, move the vehicle forward slowly (about 5 mph)…","nota":"El manual no lo dice con esas palabras: se deduce del contraste. El freno de servicio se prueba en movimiento a unas 5 mph; el de estacionamiento, con el vehículo detenido."},"26":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":70,"cita":"Some vehicles have sight glasses, see-through coolant overflow containers, or coolant recovery containers. These permit you to check the coolant level while the engine is hot.","nota":"El mismo párrafo aclara que solo se puede quitar la tapa con el motor caliente si el envase NO es parte del sistema presurizado, lo que descarta A."},"27":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 29, pregunta 27","nota":"Enunciado y opciones idénticos a la hoja 29, pregunta 27, cuya clave sí venía impresa en el folleto."},"28":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":20,"cita":"If you operate a CMV, you shall be deemed to have given your consent to alcohol testing.","nota":"Eso es el consentimiento implícito."},"29":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 27, pregunta 2","nota":"Enunciado y opciones idénticos a la hoja 27, pregunta 2, cuya clave sí venía impresa en el folleto."},"30":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 29, pregunta 29","nota":"Enunciado y opciones idénticos a la hoja 29, pregunta 29, cuya clave sí venía impresa en el folleto."},"31":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":74,"cita":"Be prepared to countersteer (turn the wheel back in the other direction) once you have passed whatever was in your path.","nota":"Definición literal de contravolanteo."},"32":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":48,"cita":"Most good drivers look at least 12 to 15 seconds ahead. […] At highway speeds, it is about a quarter of a mile.","nota":"Un cuarto de milla a velocidad de carretera."}},"12":{"45":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 27, pregunta 7","nota":"Enunciado y opciones idénticos a la hoja 27, pregunta 7, cuya clave sí venía impresa en el folleto."},"46":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 29, pregunta 26","nota":"Enunciado y opciones idénticos a la hoja 29, pregunta 26, cuya clave sí venía impresa en el folleto."},"47":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":69,"cita":"Increase engine rpm and cross the water while keeping light pressure on the brakes.","nota":"Presión ligera sobre el freno mientras se cruza el agua, tal cual."},"48":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":72,"cita":"A full stop is required at grade crossings whenever: The nature of the cargo makes a stop mandatory under state or federal regulations.","nota":"Frase literal."},"49":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 43","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 43, cuya clave sí venía impresa en el folleto."},"50":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":91,"cita":"3.3.5 – Sealed and Containerized Loads. Containerized loads generally are used when freight is carried part way by rail or ship.","nota":"Frase literal."},"1":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":101,"cita":"When the tank pressure falls to the “cut-in” pressure (around 100 psi), the governor allows the compressor to start pumping again.","nota":"El compresor arranca (cut-in) cerca de 100 psi; para (cut-out) cerca de 125."},"2":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":104,"cita":"Some vehicles, such as buses, have a separate air tank which can be used to release the spring brakes. […] When you push the control in, air from the separate air tank releases the spring brakes so you can move.","nota":"Frase literal, es el propósito del segundo tanque."}},"14":{"15":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 25, pregunta 6","nota":"Enunciado y opciones idénticos a la hoja 25, pregunta 6, cuya clave sí venía impresa en el folleto."},"16":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":75,"cita":"With this method, you apply the brakes as hard as you can without locking the wheels.","nota":"Misma pregunta que la 9 de la hoja 6, con la opción C redactada distinto, por eso se declara aparte."},"17":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":74,"cita":"For example, if your “safe” speed is 40 mph, you would not apply the brakes until your speed reaches 40 mph. You now apply the brakes hard enough to gradually reduce your speed to 35 mph and then release the brakes.","nota":"El ejemplo del manual usa exactamente las 40 mph del enunciado y baja a 35."},"18":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":101,"cita":"If the compressor has its own oil supply, check the oil level before driving.","nota":"Frase literal."},"19":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":109,"cita":"Spring Brake Test […] the parking brake (all vehicles) and tractor protection valve (combination vehicles) must be released; (engine running or not) as the driver fans off the air pressure.","nota":"El manual vigente describe la prueba abanicando el pedal para bajar la presión hasta que entren los frenos de resorte; eso es lo que describe la opción B. No hay una frase que copie la opción palabra por palabra."},"20":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":102,"cita":"Pressing and releasing the pedal unnecessarily can let air out faster than the compressor can replace it.","nota":"Misma pregunta que la 3 de la hoja 6, con las opciones redactadas distinto."}},"16":{"10":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":70,"cita":"Tires. Check the tire mounting and air pressure. […] Do not let air out or the pressure will be too low when the tires cool off. If a tire is too hot to touch, remain stopped until the tire cools off.","nota":"El mismo párrafo descarta B (no se moja la llanta, se espera a que enfríe) y C (no se saca aire)."},"11":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":39,"cita":"Exhaust System Defects: A broken exhaust system can let poison fumes into the cab or sleeper berth.","nota":"Frase literal."},"12":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":83,"cita":"However, possession and use of a drug given to a driver by a doctor is permitted if the doctor informs the driver that it will not affect safe driving ability.","nota":"Frase literal; descarta tanto la prohibición absoluta como el uso de anfetaminas."},"13":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":52,"cita":"It will take longer to stop, and it will be harder to turn without skidding, when the road is slippery.","nota":"Frase literal. La pág. 53 descarta B: «When the temperature drops, bridges will freeze before the road will»."},"14":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 27, pregunta 2","nota":"Enunciado y opciones idénticos a la hoja 27, pregunta 2, cuya clave sí venía impresa en el folleto."},"15":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":83,"cita":"BAC is determined by the amount of alcohol you drink, how fast you drink, and your weight (a small person does not have to drink as much to reach the same BAC).","nota":"El peso es uno de los tres factores; ni la tolerancia ni la edad aparecen."},"16":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":56,"cita":"On a left turn, make sure you reach the center of the intersection before you start the left turn. If you turn too soon, the left side of your vehicle may hit another vehicle because of off-tracking.","nota":"Frase literal; descarta A (empezar a girar al entrar)."},"17":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":53,"cita":"2.6.5 – Speed and Traffic Flow. When you are driving in heavy traffic, the safest speed is the speed of other vehicles.","nota":"El tráfico va a 35 mph, así que ésa es la velocidad más segura aunque el límite sea 55."},"18":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":42,"cita":"Turn off the Engine and Check the Lights. Make sure the parking brake is set, turn off the engine, and take the key with you.","nota":"Sin frase literal en el manual. Se deduce del hardware: en la mayoría de los vehículos las direccionales y las intermitentes de emergencia usan los mismos focos, así que no pueden comprobarse a la vez."},"19":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":49,"cita":"When merging, use your mirrors to make sure the gap in traffic is large enough for you to enter safely.","nota":"Frase literal; la pág. 57 añade que un vehículo pesado necesita un hueco mucho mayor que un auto."},"20":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":46,"cita":"Back slowly. Back and turn toward the driver's side whenever possible. Use a helper whenever possible.","nota":"Por descarte, igual que en la hoja 4: A y B están literales en el manual, así que la falsa es la de golpear el andén."}},"18":{"33":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 11, pregunta 37","nota":"Enunciado y opciones idénticos a la hoja 11, pregunta 37, cuya clave sí venía impresa en el folleto."},"34":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":53,"cita":"When the temperature drops, bridges will freeze before the road will.","nota":"Frase literal."},"35":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":45,"cita":"Apply the parking brake whenever necessary to keep from rolling back. Release the parking brake only when you have applied enough engine power to keep from rolling back.","nota":"Frase literal; descarta B (dejar rodar hacia atrás) y A (patinar el embrague)."},"36":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":48,"cita":"Most good drivers look at least 12 to 15 seconds ahead.","nota":"Frase literal."},"37":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":54,"cita":"Observe the posted speed limits at all times when approaching and driving through a work zone. […] Sometimes the pavement drops off sharply near the edge of the road.","nota":"Por descarte: el manual pide bajar la velocidad siempre, no solo si hay trabajadores cerca, y no menciona encender las luces de estacionamiento."},"38":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":89,"cita":"GCWR will be determined by adding the GVWR of the power unit, the total weight of the towed unit, and any load thereon.","nota":"Ésa es la definición de gross combination weight."},"39":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":51,"cita":"Back beyond any hill, curve, or other obstruction that prevents other drivers from seeing the vehicle within 500 feet. […] If line of sight view is obstructed due to hill or curve, move the rear-most triangle to a point back down the road so warning is provided.","nota":"Frase literal. Además la pág. 50 fija el plazo en 10 minutos, no 5, lo que descarta C."},"40":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":80,"cita":"Cargo. Flammable cargo, improperly sealed or loaded cargo, and poor ventilation. […] Tires. Under-inflated tires and dual tires that touch.","nota":"La lista de causas incluye la mala ventilación de la carga y desmiente A."},"41":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 1, pregunta 3","nota":"Enunciado y opciones idénticos a la hoja 1, pregunta 3, cuya clave sí venía impresa en el folleto."},"42":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":52,"cita":"The heavier the vehicle, the more work the brakes must do to stop it and the more heat they absorb.","nota":"Frase literal; la pág. 112 desmiente C: «Brake fade results from excessive heat»."},"43":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":74,"cita":"In order to turn quickly, you must have a firm grip on the steering wheel with both hands.","nota":"Frase literal. La pág. 79 desmiente A: «Stopping is not always the safest thing to do in an emergency»."},"44":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":79,"cita":"With vehicles towing trailers, a drive-wheel skid can let the trailer push the towing vehicle sideways, causing a sudden jackknife.","nota":"Frase literal. El mismo párrafo desmiente A: «Locked wheels have less traction than rolling wheels»."},"45":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":41,"cita":"Pressure should come up to normal within seconds after the engine is started. […] Should begin gradual rise to normal operating range.","nota":"La presión de aceite sube en segundos (descarta B) y la temperatura del refrigerante es la que sube de forma gradual."}},"20":{"1":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 1, pregunta 8","nota":"Enunciado y opciones idénticos a la hoja 1, pregunta 8, cuya clave sí venía impresa en el folleto."},"2":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":46,"cita":"Back slowly. Back and turn toward the driver's side whenever possible. Use a helper whenever possible.","nota":"Por descarte, igual que en la hoja 4: A y B están literales en el manual, así que la falsa es la de golpear el andén."},"3":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 15, pregunta 2","nota":"Enunciado y opciones idénticos a la hoja 15, pregunta 2, cuya clave sí venía impresa en el folleto."},"4":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 1, pregunta 1","nota":"Enunciado y opciones idénticos a la hoja 1, pregunta 1, cuya clave sí venía impresa en el folleto."},"5":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":48,"cita":"Most good drivers look at least 12 to 15 seconds ahead. […] At highway speeds, it is about a quarter of a mile.","nota":"Un cuarto de milla a velocidad de carretera."},"6":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":50,"cita":"Put your turn signal on before changing lanes. Change lanes slowly and smoothly.","nota":"Las dos mitades de la opción B están literales en el manual."},"7":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":80,"cita":"2.20.1 – Protect the Area. The first thing to do at an accident scene is to keep another accident from happening in the same spot.","nota":"Avisar a las autoridades es el paso 2; sin radio CB, el manual dice esperar a que el área esté protegida antes de ir a llamar."},"8":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 3, pregunta 22","nota":"Enunciado y opciones idénticos a la hoja 3, pregunta 22, cuya clave sí venía impresa en el folleto."},"9":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 50","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 50, cuya clave sí venía impresa en el folleto."},"10":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 47","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 47, cuya clave sí venía impresa en el folleto."}},"22":{"22":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":74,"cita":"Know escape ramp locations on your route.","nota":"La sección de conducción en montaña lo pide expresamente antes de bajar una pendiente."},"23":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 3, pregunta 26","nota":"Enunciado y opciones idénticos a la hoja 3, pregunta 26, cuya clave sí venía impresa en el folleto."},"24":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 46","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 46, cuya clave sí venía impresa en el folleto."},"25":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":83,"cita":"Alcohol affects judgment, vision, coordination, and reaction time. […] This is a fixed rate, so only time, not black coffee or a cold shower, will sober you up.","nota":"El manual no dice que el juicio se afecte «primero», pero descarta A (el cuerpo elimina alcohol a ritmo fijo) y B (el alcohol empeora el tiempo de reacción)."},"26":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":68,"cita":"The best advice for driving in fog is do not. […] It is preferable that you pull off the road into a rest area or truck stop until visibility is better.","nota":"Frase literal."},"27":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":51,"cita":"When putting out the triangles, hold them between yourself and the oncoming traffic for your own safety.","nota":"Coincide palabra por palabra con la opción."},"28":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":92,"cita":"Dry bulk tanks require special care because they have a high center of gravity, and the load can shift.","nota":"Misma frase del manual, sección 3.4.1."},"29":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 3, pregunta 23","nota":"Enunciado y opciones idénticos a la hoja 3, pregunta 23, cuya clave sí venía impresa en el folleto."},"30":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 49","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 49, cuya clave sí venía impresa en el folleto."},"31":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 1, pregunta 6","nota":"Enunciado y opciones idénticos a la hoja 1, pregunta 6, cuya clave sí venía impresa en el folleto."},"32":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":96,"cita":"There are 9 different 4 inch, diamond-shaped hazard labels.","nota":"Cuatro pulgadas y forma de diamante, no circular."},"33":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 48","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 48, cuya clave sí venía impresa en el folleto."}},"24":{"44":{"clave":"A","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":45,"cita":"Rough acceleration can cause mechanical damage. When pulling a trailer, rough acceleration can damage the coupling.","nota":"Por descarte: el manual nombra el daño mecánico y el daño al acoplamiento, y no menciona daño a las llantas."},"45":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":79,"cita":"Skids caused by acceleration usually happen on ice or snow. Taking your foot off the accelerator can easily stop them.","nota":"OJO: el manual vigente corrige un patinaje por FRENADO con «Stop Braking», opción que el cuestionario no ofrece. De las tres impresas, quitar el acelerador es la única que el manual respalda para hielo o nieve."},"46":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 45","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 45, cuya clave sí venía impresa en el folleto."},"47":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 3, pregunta 24","nota":"Enunciado y opciones idénticos a la hoja 3, pregunta 24, cuya clave sí venía impresa en el folleto."},"48":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 13","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 13, cuya clave sí venía impresa en el folleto."},"49":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 1, pregunta 10","nota":"Enunciado y opciones idénticos a la hoja 1, pregunta 10, cuya clave sí venía impresa en el folleto."},"50":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":51,"cita":"This is the distance your vehicle travels, in ideal conditions, from the time your eyes see a hazard until your brain recognizes it.","nota":"Definición literal de perception distance."},"1":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":102,"cita":"When you push the brake pedal, air is let into each brake chamber. […] Pushing the pedal down harder applies more air pressure.","nota":"El pedal dosifica la presión de aire aplicada a los frenos."},"2":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":75,"cita":"You should brake in a way that will keep your vehicle in a straight line and allow you to turn if it becomes necessary.","nota":"Misma pregunta que la 13 de la hoja 6, con las opciones redactadas distinto."},"3":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":101,"cita":"Service brake system applies and releases the brakes when you use the brake pedal during normal driving.","nota":"Definición literal."},"4":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":104,"cita":"A parking brake control in the cab allows the driver to let the air out of the spring brakes. […] If the air pressure is removed, the springs put on the brakes.","nota":"REVISABLE. El manual no responde la pregunta con esas palabras. En condiciones normales el control de estacionamiento aplica los frenos sacando el aire de las cámaras de resorte, que es lo que describe la opción B; pero «dejar salir el aire del sistema de frenos de aire» es una redacción más amplia que la del manual."}},"26":{"16":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":101,"cita":"5.1.2 – Air Compressor Governor. The governor controls when the air compressor will pump air into the air storage tanks.","nota":"El gobernador controla CUÁNDO se bombea aire; no la velocidad del compresor ni la presión aplicada a los frenos."},"17":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":110,"cita":"Static Leakage Test […] Time for 1 minute. The air pressure should not drop more than: 2 psi for single vehicles.","nota":"Un camión o autobús rígido es «single vehicle»: 2 psi por minuto."},"18":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":109,"cita":"Check the Rate of Air Pressure Buildup […] For dual air systems, the pressure should build from approximately 85 to 100 psi within 45 seconds.","nota":"Sin frase literal. Se deduce: si el sistema no repone aire al ritmo exigido, la presión puede caer demasiado durante la marcha. El evaporador de alcohol (opción B) no interviene en el ritmo de llenado."},"19":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":113,"cita":"5.4.7 – Low Air Pressure. If the low air pressure warning comes on, stop and safely park your vehicle as soon as possible.","nota":"No distingue si falla un circuito o los dos: hay que detenerse y estacionar."},"20":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":110,"cita":"Test Service Brakes: Wait for normal air pressure, release the parking brake, move the vehicle forward slowly (about 5 mph), and apply the brakes firmly using the brake pedal.","nota":"Procedimiento literal del manual."}},"28":{"11":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 19","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 19, cuya clave sí venía impresa en el folleto."},"12":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 13","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 13, cuya clave sí venía impresa en el folleto."},"13":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":58,"cita":"Make sure you are going slowly enough before you get on the curved part of an off or on ramp.","nota":"Además el manual advierte que el límite señalado en las rampas está pensado para autos, no para vehículos pesados."},"14":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":72,"cita":"A full stop is required at grade crossings whenever: The nature of the cargo makes a stop mandatory under state or federal regulations.","nota":"Frase literal."},"15":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":47,"cita":"2.3.4 – Retarders. Some vehicles have “retarders.” Retarders help slow a vehicle, reducing the need for using your brakes.","nota":"Frase literal. El mismo apartado advierte que en piso resbaloso el retardador puede PROVOCAR patinaje, lo que descarta B."},"16":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 11, pregunta 36","nota":"Enunciado y opciones idénticos a la hoja 11, pregunta 36, cuya clave sí venía impresa en el folleto."},"17":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":55,"cita":"Increase Your Following Distance. Open up room in front of you to help you avoid having to make sudden speed or direction changes.","nota":"Es la recomendación literal del manual para cuando te van pegado atrás."},"18":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":70,"cita":"Some vehicles have sight glasses, see-through coolant overflow containers, or coolant recovery containers. These permit you to check the coolant level while the engine is hot.","nota":"El mismo párrafo aclara que solo se puede quitar la tapa con el motor caliente si el envase NO es parte del sistema presurizado, lo que descarta A."},"19":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":74,"cita":"Be prepared to countersteer (turn the wheel back in the other direction) once you have passed whatever was in your path.","nota":"Definición literal de contravolanteo."},"20":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 5, pregunta 43","nota":"Enunciado y opciones idénticos a la hoja 5, pregunta 43, cuya clave sí venía impresa en el folleto."}},"30":{"34":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":91,"cita":"3.3.5 – Sealed and Containerized Loads. Containerized loads generally are used when freight is carried part way by rail or ship.","nota":"Misma pregunta que la 50 de la hoja 12; aquí «tiedown» va escrito en una sola palabra."},"35":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 9","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 9, cuya clave sí venía impresa en el folleto."},"36":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":48,"cita":"Most good drivers look at least 12 to 15 seconds ahead. […] At highway speeds, it is about a quarter of a mile.","nota":"Un cuarto de milla a velocidad de carretera."},"37":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":117,"cita":"6.1.6 – Turn Wide. When a vehicle goes around a corner, the rear wheels follow a different path than the front wheels. […] the rear wheels of the last trailer will off-track the most.","nota":"El término del manual es off-tracking."},"38":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 11, pregunta 43","nota":"Enunciado y opciones idénticos a la hoja 11, pregunta 43, cuya clave sí venía impresa en el folleto."},"39":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 14","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 14, cuya clave sí venía impresa en el folleto."},"40":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 10","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 10, cuya clave sí venía impresa en el folleto."},"41":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 16","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 16, cuya clave sí venía impresa en el folleto."},"42":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":52,"cita":"55 [mph] 419' Total Stopping Distance […] At 60 mph, your stopping distance is greater than the length of an American football field.","nota":"El manual vigente da 419 pies a 55 mph; un campo de fútbol americano mide 300. De las tres opciones impresas, «la longitud de un campo» es la única del orden correcto."},"43":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":110,"cita":"Test Parking Brake: Fasten your seat belt. Set the parking brake, and gently pull against it in a low gear to test that the parking brake will hold. Test Service Brakes: Wait for normal air pressure, release the parking brake, move the vehicle forward slowly (about 5 mph)…","nota":"El manual no lo dice con esas palabras: se deduce del contraste. El freno de servicio se prueba en movimiento a unas 5 mph; el de estacionamiento, con el vehículo detenido."},"44":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-650","pagina":80,"cita":"Vehicle Inspection. Make a complete inspection of the electrical, fuel, and exhaust systems, tires, and cargo. […] Cargo. Flammable cargo, improperly sealed or loaded cargo, and poor ventilation.","nota":"Por descarte: la lista de causas de incendio incluye el sistema eléctrico y la ventilación de la carga, pero no el nivel de líquido de la batería."},"45":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 9, pregunta 11","nota":"Enunciado y opciones idénticos a la hoja 9, pregunta 11, cuya clave sí venía impresa en el folleto."}},"32":{"1":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":73,"cita":"With older trucks, a rule for choosing gears is to use the same gear going down a hill that you would need to climb the hill. […] For that reason, drivers of modern trucks may have to use lower gears going down a hill than required to go up the hill.","nota":"El enunciado dice camión NUEVO, así que aplica la segunda frase: una marcha más baja."},"2":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 19, pregunta 48","nota":"Enunciado y opciones idénticos a la hoja 19, pregunta 48, cuya clave sí venía impresa en el folleto."},"3":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 19, pregunta 49","nota":"Enunciado y opciones idénticos a la hoja 19, pregunta 49, cuya clave sí venía impresa en el folleto."},"4":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 19, pregunta 50","nota":"Enunciado y opciones idénticos a la hoja 19, pregunta 50, cuya clave sí venía impresa en el folleto."}},"34":{"12":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 39, pregunta 9","nota":"Enunciado y opciones idénticos a la hoja 39, pregunta 9, cuya clave sí venía impresa en el folleto."},"13":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":98,"cita":"Do not discharge such riders where it would be unsafe for them. It may be safer at the next scheduled stop or a well-lit area where there are other people.","nota":"El criterio es la seguridad del pasajero, no la comodidad del conductor ni la cercanía de una comisaría."},"14":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":96,"cita":"Never drive with an open emergency exit door or window.","nota":"La luz roja solo es obligatoria si el autobús la tiene («If there is a red emergency door light, it must work»), así que B es condicional y A es la regla absoluta."},"15":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 39, pregunta 3","nota":"Enunciado y opciones idénticos a la hoja 39, pregunta 3, cuya clave sí venía impresa en el folleto."},"16":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"Buses must never carry: […] More than 500 pounds total of allowed HazMat, and no more than 100 pounds of any 1 class.","nota":"El tope total son 500 libras."},"17":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":55,"cita":"One good rule says you need at least 1 second for each 10 feet of vehicle length at speeds below 40 mph. […] For example, if you are driving a 40-foot vehicle, you should leave 4 seconds.","nota":"El ejemplo del manual usa justo un vehículo de 40 pies a menos de 40 mph: 4 segundos."},"18":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":96,"cita":"Do not allow riders to leave carry-on baggage in a doorway or aisle.","nota":"Frase literal."},"19":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 35, pregunta 7","nota":"Enunciado y opciones idénticos a la hoja 35, pregunta 7, cuya clave sí venía impresa en el folleto."},"20":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":57,"cita":"A hazard is any road condition or other road user (driver, motorcyclist, bicyclist, and pedestrian) that is a possible danger.","nota":"La definición del manual abarca tanto a otros usuarios como a las condiciones del camino, así que A y B se quedan cortas."}},"36":{"11":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":100,"cita":"Only tow or push the bus to the nearest safe spot to discharge passengers.","nota":"Al punto seguro más cercano, no al taller."},"12":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"More than 500 pounds total of allowed HazMat, and no more than 100 pounds of any 1 class.","nota":"Tope total: 500 libras."},"13":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"More than 500 pounds total of allowed HazMat, and no more than 100 pounds of any 1 class.","nota":"Tope por clase: 100 libras."},"14":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":95,"cita":"Tires (front wheels must not have recapped or regrooved tires).","nota":"Prohibidas en las ruedas delanteras, permitidas en el resto."},"15":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":98,"cita":"Do not discharge such riders where it would be unsafe for them.","nota":"Misma pregunta que la 13 de la hoja 34, con las opciones en otro orden."},"16":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"4.2.3 – Standee Line. No rider may stand forward of the rear of the driver's seat. Buses designed to allow standing must have a 2-inch line on the floor or some other means of showing riders where they cannot stand.","nota":"Nadie puede ir de pie delante de la línea de seguridad."},"17":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":98,"cita":"While driving, scan the interior of your bus, as well as the road ahead, to the sides, and to the rear.","nota":"Frase literal."},"18":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":98,"cita":"If your bus leans toward the outside on a banked curve, you are driving too fast.","nota":"Frase literal."},"19":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":52,"cita":"When you double your speed from 20 to 40 mph, the impact is 4 times greater. The braking distance is also 4 times longer.","nota":"Cuatro veces más distancia de frenado al pasar de 20 a 40 mph."},"20":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"Buses must never carry: Division 2.3 poison gas, liquid Class 6 poison, tear gas, or irritating material.","nota":"El gas lacrimógeno y los materiales irritantes están prohibidos siempre; la munición ORM-D y los medicamentos sí se permiten."}},"38":{"11":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"Buses may carry small-arms ammunition labeled ORM-D, emergency hospital supplies, and drugs. […] Explosives in the space occupied by people, except small-arms ammunition.","nota":"La munición de armas cortas ORM-D es la excepción permitida en el área de pasajeros; los radiactivos etiquetados y los venenos líquidos Clase 6 están prohibidos ahí."},"12":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":100,"cita":"Do not tow or push a disabled bus with riders aboard the vehicle, unless getting off would be unsafe.","nota":"Frase literal."},"13":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":99,"cita":"Stop at drawbridges that do not have a signal light or traffic control attendant. Stop at least 50 feet before the draw of the bridge.","nota":"50 pies, exactamente el supuesto del enunciado."},"14":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":141,"cita":"8.3.3 – Curves. Slow down before curves, and then accelerate slightly through the curve.","nota":"Frase literal; la pág. 47 explica que acelerar un poco da estabilidad al vehículo en la curva."},"15":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":99,"cita":"If your bus has a manual transmission, never change gears while crossing the tracks.","nota":"Frase literal. La misma página fija la parada entre 15 y 50 pies, lo que descarta B."},"16":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":99,"cita":"If you work for an interstate carrier, you must complete a written inspection report for each bus driven. The report must specify each bus and list any defect that would affect safety or result in a breakdown.","nota":"Frase literal."},"17":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"4.2.3 – Standee Line. No rider may stand forward of the rear of the driver's seat.","nota":"Misma regla que la pregunta 16 de la hoja 36, con las opciones en otro orden."},"18":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":48,"cita":"Good drivers shift their attention back and forth, near and far.","nota":"Frase literal; la misma página fija 12–15 segundos, lo que descarta C."},"19":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":55,"cita":"1 second required for each 10 feet of vehicle length at speeds under 40 MPH. Above 40 MPH use same formula, then add 1 second for the additional speed.","nota":"30 pies = 3 segundos, más 1 segundo por ir a 45 mph: 4 segundos."},"20":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":98,"cita":"Many buses have convex mirrors that show a wider area than flat mirrors. […] Remember, these mirrors make things seem smaller and farther away than they really are.","nota":"Frase literal."}},"40":{"11":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":98,"cita":"Do not discharge such riders where it would be unsafe for them.","nota":"Misma pregunta que la 13 de la hoja 34; aquí la opción se imprime como «That is safe as possible»."},"12":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":96,"cita":"Never drive with an open emergency exit door or window.","nota":"La luz roja solo es obligatoria si el autobús la tiene («If there is a red emergency door light, it must work»), así que B es condicional y A es la regla absoluta."},"13":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"Buses must never carry: […] More than 500 pounds total of allowed HazMat, and no more than 100 pounds of any 1 class.","nota":"El tope total son 500 libras."},"14":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":55,"cita":"One good rule says you need at least 1 second for each 10 feet of vehicle length at speeds below 40 mph. […] For example, if you are driving a 40-foot vehicle, you should leave 4 seconds.","nota":"El ejemplo del manual usa justo un vehículo de 40 pies a menos de 40 mph: 4 segundos."},"15":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":57,"cita":"A hazard is any road condition or other road user (driver, motorcyclist, bicyclist, and pedestrian) that is a possible danger.","nota":"La definición del manual abarca tanto a otros usuarios como a las condiciones del camino, así que A y B se quedan cortas."},"16":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 35, pregunta 7","nota":"Enunciado y opciones idénticos a la hoja 35, pregunta 7, cuya clave sí venía impresa en el folleto."},"17":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":97,"cita":"Riders sometimes board a bus with an unlabeled HazMat. Do not allow riders to carry on common hazards such as car batteries or gasoline.","nota":"El manual nombra justo esos dos ejemplos: batería de auto y gasolina."},"18":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-650","pagina":96,"cita":"Do not allow riders to leave carry-on baggage in a doorway or aisle.","nota":"Frase literal."},"19":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 33, pregunta 6","nota":"Enunciado y opciones idénticos a la hoja 33, pregunta 6, cuya clave sí venía impresa en el folleto."},"20":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 33, pregunta 9","nota":"Enunciado y opciones idénticos a la hoja 33, pregunta 9, cuya clave sí venía impresa en el folleto."}},"42":{"11":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 43, pregunta 3","nota":"Enunciado y opciones idénticos a la hoja 43, pregunta 3, cuya clave sí venía impresa en el folleto."},"12":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 49, pregunta 3","nota":"Enunciado y opciones idénticos a la hoja 49, pregunta 3, cuya clave sí venía impresa en el folleto."},"13":{"clave":"A","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":63,"cita":"Tailgating (Following Too Closely). Tailgating makes it harder for you to see the road ahead because the vehicle in front of you blocks your view.","nota":"Por descarte: seguir demasiado cerca sí es infracción sancionable (descarta B) y no reduce choques (descarta C). El manual la trata dentro de la conducción agresiva."},"14":{"clave":"C","origen":"duplicado","certeza":"exacta","fuente":"hoja 50, pregunta 13","nota":"Enunciado y opciones idénticos a la hoja 50, pregunta 13, cuya clave sí venía impresa en el folleto."},"15":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 50, pregunta 10","nota":"Enunciado y opciones idénticos a la hoja 50, pregunta 10, cuya clave sí venía impresa en el folleto."},"16":{"clave":"A","origen":"duplicado","certeza":"exacta","fuente":"hoja 49, pregunta 4","nota":"Enunciado y opciones idénticos a la hoja 49, pregunta 4, cuya clave sí venía impresa en el folleto."},"17":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 50, pregunta 16","nota":"Enunciado y opciones idénticos a la hoja 50, pregunta 16, cuya clave sí venía impresa en el folleto."},"18":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":63,"cita":"If a vehicle merges in front of you too closely, take your foot off the accelerator.","nota":"Frase literal."}},"44":{"11":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":73,"cita":"Ride at least 10 inches from the airbag cover, as long as you can maintain full control of your vehicle.","nota":"Diez pulgadas como mínimo."},"12":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":24,"cita":"Check for bicyclists in your blind spots.","nota":"Los ciclistas no circulan de frente al tráfico (descarta A) ni tienen preferencia siempre (descarta C)."},"13":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":46,"cita":"Enter heading to the right when there is a big enough gap in traffic to merge safely.","nota":"Frase literal."},"14":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":73,"cita":"Avoid weaving in and out of freeway lanes. […] Do not weave in and out of traffic.","nota":"El manual lo prohíbe pero no explica el motivo con esas palabras. Por descarte: zigzaguear ni mejora el flujo (A) ni te hace llegar más seguro y rápido (C)."},"15":{"clave":"B","origen":"ia","certeza":"cambio","manual":"DL-600","pagina":72,"cita":"Children who are under 8 years old, or who are less than 4 feet 9 inches tall [must be secured in a child passenger restraint system].","nota":"LA LEY CAMBIÓ. El cuestionario es de 2003, cuando la regla era menor de 6 años Y menos de 60 libras: solo el niño de 5 años y 55 libras la cumplía. Con la ley vigente los TRES casos requerirían silla, porque los tres son menores de 8 años."},"16":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":17,"cita":"When conditions (such as clouds, dust, smoke, or fog) prevent you from seeing other vehicles.","nota":"El criterio del manual es la visibilidad, no una hora fija ni una distancia de dos millas."},"17":{"clave":"B","origen":"duplicado","certeza":"exacta","fuente":"hoja 41, pregunta 6","nota":"Enunciado y opciones idénticos a la hoja 41, pregunta 6, cuya clave sí venía impresa en el folleto."},"18":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":19,"cita":"Single Solid Yellow Line. A single solid yellow line marks the center of a road with two-way traffic.","nota":"El amarillo separa sentidos opuestos; el blanco separa carriles del mismo sentido."}},"46":{"10":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":50,"cita":"Check for motorcyclists before you open your door next to traffic.","nota":"La regla es revisar el lado del tráfico antes de abrir. Las ruedas hacia la banqueta solo aplican en pendiente, no en calle plana."},"11":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":90,"cita":"Yield means to wait for, slow down, and be ready to stop (if necessary) to allow other vehicles or pedestrians who have right-of-way to proceed.","nota":"En un cruce sin señales no hay que parar siempre (descarta A) ni ceder a todos (descarta B): la regla del manual es reducir y estar listo para parar."},"12":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":50,"cita":"Never turn in front of an approaching light rail vehicle.","nota":"Frase literal. El manual también advierte que el tren ligero es silencioso y rápido, lo que descarta C."},"13":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":47,"cita":"Pedestrians have the right-of-way in marked or unmarked crosswalks.","nota":"Un cruce sin líneas pintadas sigue teniendo cruce peatonal implícito."},"14":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":30,"cita":"Before you pass, look ahead for road conditions that may cause other vehicles to move into your lane.","nota":"Por descarte: la doble línea amarilla continua PROHÍBE rebasar (descarta A) y subir a 60 mph excedería el límite (descarta B). Lo que hace falta es hueco en el sentido contrario."},"15":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":66,"cita":"For sharp curves, slow down as you approach and move through.","nota":"REVISABLE. El manual vigente no explica el motivo con estas palabras. La opción B habla de un «jalón hacia adentro», cuando la fuerza que se siente en una curva es hacia afuera; queda C, que es además la redacción del manual de 2003."},"16":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":22,"cita":"You must use a turnout area or lane to let other vehicles pass when you are driving slowly on a two-lane road, where passing is unsafe, and there are five or more vehicles following you.","nota":"Cinco o más vehículos detrás: es obligación legal orillarse."},"17":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":70,"cita":"If the fog becomes too thick to drive safely, consider pulling off the road.","nota":"El enunciado ya dice que no se ve el camino y que los limpiadores no ayudan: es el caso de salirse por completo."},"18":{"clave":"C","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":51,"cita":"Give the right-of-way to any law enforcement vehicle, fire engine, ambulance, or other emergency vehicle using a siren and red lights. Drive to the right edge of the road and stop until the emergency vehicle(s) have passed.","nota":"El manual manda orillarse a la derecha y parar, pero no aborda el caso de ir ya cruzando la intersección. Parar dentro del crucero la bloquearía, así que se completa el cruce y luego se orilla."}},"48":{"10":{"clave":"B","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":22,"cita":"Merge completely into the center left turn lane so you do not block traffic.","nota":"Es el carril central de vuelta izquierda de doble sentido. Comprueba en el escaneo que la figura sea ésa."},"11":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":17,"cita":"If you need to use your windshield wipers due to fog, rain, or snow, you must turn on your low-beam headlights.","nota":"Luces bajas, no de estacionamiento ni el tablero."},"12":{"clave":"A","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":39,"cita":"When at or approaching traffic signals or signs, yield to pedestrians, bicyclists, and other nearby vehicles that may have the right-of-way.","nota":"REVISABLE. Sin frase literal. La preferencia se cede a quien la tiene según la regla, no siempre; ceder el paso a todos rompe el orden previsible del cruce y retrasa el tráfico."},"13":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":29,"cita":"Check your blind spots for vehicles, motorcyclists, bicyclists, and pedestrians each time.","nota":"Por descarte: oír no basta en un cruce de ferrocarril (descarta A) y concentrarse solo al frente contradice el rastreo lateral que pide el manual (descarta C)."},"14":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":17,"cita":"At least five seconds before you change lanes on a freeway.","nota":"Frase literal."},"15":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":63,"cita":"Tailgating makes it harder for you to see the road ahead because the vehicle in front of you blocks your view.","nota":"Un camión tapa más; por eso hace falta más espacio para ver. Además, el mayor peso hace que frene MÁS despacio, lo que descarta B."},"16":{"clave":"B","origen":"ia","certeza":"deducida","manual":"DL-600","pagina":55,"cita":"Fines are also doubled in highway construction or maintenance zones when workers are present.","nota":"Por descarte: las multas NO son iguales, se duplican (descarta A) y hay que bajar la velocidad siempre, no solo si crees que hay trabajadores (descarta C)."},"17":{"clave":"C","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":24,"cita":"Right Turn Against a Red Arrow. You may not turn right if you are stopped at a red arrow light.","nota":"Contra flecha roja no se puede girar ni deteniéndose antes; contra luz roja sólida sí se puede dar vuelta a la derecha tras hacer alto total."},"18":{"clave":"A","origen":"ia","certeza":"confirmada","manual":"DL-600","pagina":40,"cita":"Do not enter the intersection if you cannot get completely across before the traffic signal light turns red.","nota":"Sin excepciones; la pág. 45 añade que bloquear el crucero es ilegal."}}};
